# the card shown is the first red flag in this order
PRIORITY = ["suicidal_ideation", "seizure", "severe_bleeding", "high_fever_infant", "unconsciousness", "stroke_symptoms", "chest_pain"]


def card(flags: list[str], lang: str) -> dict:
    """-> {title, call, steps, explanation} for the most specific red flag, else the generic card."""
    for f in PRIORITY:
        if f in flags:
            c = CARDS[f][lang]
            call = CALL[lang] + ([MIND_LINE[lang]] if f == "suicidal_ideation" else [])
            return {**c, "call": call}
    return {**GENERIC[lang], "call": CALL[lang]}


EMERGENCY = {lang: {**GENERIC[lang], "call": CALL[lang]} for lang in CALL}  # backwards compatible: the generic card
